export const ETM_SCRIPTS = {"etm-launcher.ps1":{"src":"param(\n  [string]$Config = (Join-Path $PSScriptRoot 'etm.config.json'),\n  [string]$SerialRoot = '', [string]$EtmRoot = '', [int]$Port = 0,\n  [switch]$CheckOnly, [switch]$NoBrowser\n)\n$ErrorActionPreference = 'Stop'\ntry {\n  $settings = if (Test-Path -LiteralPath $Config) { Get-Content -LiteralPath $Config -Raw -Encoding UTF8 | ConvertFrom-Json } else { $null }\n  if (-not $SerialRoot -and $settings) { $SerialRoot = $settings.serialRoot }\n  if (-not $EtmRoot -and $settings) { $EtmRoot = $settings.etmRoot }\n  if (-not $Port) { $Port = if ($settings -and $settings.port) { [int]$settings.port } else { 8878 } }\n  if ($Port -lt 1024 -or $Port -gt 65535) { throw '端口必须在 1024～65535 之间。' }\n  $parents = @($PSScriptRoot, (Split-Path $PSScriptRoot -Parent), (Split-Path (Split-Path $PSScriptRoot -Parent) -Parent))\n  function Find-Project([string]$chosen, [string]$name, [string]$marker) {\n    if ($chosen) {\n      if (-not [IO.Path]::IsPathRooted($chosen)) { $chosen = Join-Path $PSScriptRoot $chosen }\n      $candidates = @($chosen)\n    } else { $candidates = @($parents | ForEach-Object { $_; Join-Path $_ $name }) }\n    foreach ($candidate in $candidates) {\n      if (Test-Path -LiteralPath (Join-Path $candidate $marker)) { return (Resolve-Path -LiteralPath $candidate).Path }\n    }\n    throw \"找不到 $name；请在 etm.config.json 中填写工程目录（或在页面填写后重新下载）。\"\n  }\n  $SerialRoot = Find-Project $SerialRoot 'web-serial-rtt-tools' 'app\\etm\\view.js'\n  $EtmRoot = Find-Project $EtmRoot 'web-etm-trace' 'web\\app\\embedding.js'\n  foreach ($required in @('server.py', 'requirements.txt', 'build-native\\etm_decode.exe')) {\n    if (-not (Test-Path -LiteralPath (Join-Path $EtmRoot $required))) {\n      throw \"ETM 缺少 $required。请先按照 ETM 工程 README 安装依赖、构建解码器，再启动本地桥。\"\n    }\n  }\n  $server = Join-Path $PSScriptRoot 'serve-etm.py'\n  if (-not (Test-Path -LiteralPath $server)) { throw '启动包不完整：缺少 serve-etm.py，请重新下载完整 ZIP。' }\n  $python = Get-Command python.exe -ErrorAction SilentlyContinue\n  $pythonArgs = @()\n  if (-not $python) { $python = Get-Command py.exe -ErrorAction SilentlyContinue; $pythonArgs = @('-3') }\n  if (-not $python) { throw '没有找到 Python 3，请安装 Python 并启用 PATH，再双击启动器。' }\n  & $python.Source @pythonArgs -X utf8 -c 'import sys; assert sys.version_info >= (3,9); import flask, werkzeug, elftools, capstone'\n  if ($LASTEXITCODE -ne 0) { throw \"Python 版本或依赖不满足；需要 Python 3.9+，请执行：python -m pip install -r `\"$EtmRoot\\requirements.txt`\"\" }\n  $url = \"http://127.0.0.1:$Port/\"\n  $existing = $null\n  try { $existing = Invoke-RestMethod -Uri ($url + 'etm-launcher.json') -TimeoutSec 2 } catch {}\n  if ($existing -and $existing.protocol -eq 1 -and $existing.serialRoot -eq $SerialRoot -and $existing.etmRoot -eq $EtmRoot) {\n    Write-Host \"本地工作台已运行：$url#etm\"\n    if (-not $CheckOnly -and -not $NoBrowser) { Start-Process ($url + '#etm') }\n    exit 0\n  }\n  $listener = [Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback, $Port)\n  try { $listener.Start() } catch { throw \"端口 $Port 已被其他服务占用；请更换端口，不会停止已有服务。\" } finally { $listener.Stop() }\n  Write-Host \"工具箱：$SerialRoot\"\n  Write-Host \"ETM：$EtmRoot\"\n  Write-Host \"预检通过。KingstVIS 需开启 Socket，并使能 CH0～4。\"\n  if ($CheckOnly) { exit 0 }\n  if (-not $NoBrowser) {\n    # 等待同源服务准备完毕后才打开网页；退出会连同这个等待任务一起释放。\n    $browserJob = Start-Job -ArgumentList $url -ScriptBlock {\n      param($base)\n      for ($i=0; $i -lt 60; $i++) {\n        try { $ready = Invoke-RestMethod ($base + 'etm-launcher.json') -TimeoutSec 1; if ($ready.protocol -eq 1) { Start-Process ($base + '#etm'); return } } catch {}\n        Start-Sleep -Milliseconds 500\n      }\n    }\n  }\n  Write-Host \"启动 ETM 桥：$url#etm（退出请按 Ctrl+C）\"\n  & $python.Source @pythonArgs -X utf8 $server --serial-root $SerialRoot --etm-root $EtmRoot --port $Port\n  if ($LASTEXITCODE -ne 0) { throw '本地桥启动失败，请查看上面的错误。' }\n} catch { Write-Host (\"[错误] \" + $_.Exception.Message) -ForegroundColor Red; exit 1 }\nfinally { if ($browserJob) { Stop-Job $browserJob; Remove-Job $browserJob } }\n","sha256":"6ce8899097eb59c79ff94e1f96fd83a676b1d92e8809fa2cfc989e3f30a04c51"},"serve-etm.py":{"src":"\"\"\"One loopback origin for the toolbox and the sibling ETM project.\n\npython tools/dev/serve-etm.py --etm-root ../web-etm-trace --port 8878\nThe ETM backend, decoder and records stay in their own repository.\n\"\"\"\nimport argparse\nimport importlib.util\nimport mimetypes\nimport re\nimport sys\nfrom pathlib import Path\nfrom flask import Flask,abort,jsonify,request,send_from_directory\nfrom werkzeug.middleware.dispatcher import DispatcherMiddleware\nfrom werkzeug.serving import run_simple\n\nROOT=Path(__file__).resolve().parents[2]\n\n\ndef create_application(etm_root,serial_root=ROOT):\n    etm_root=Path(etm_root).resolve();serial_root=Path(serial_root).resolve()\n    source=etm_root/'server.py'\n    if not source.is_file():raise ValueError('找不到 ETM 工程，请用 --etm-root 指定其目录')\n    spec=importlib.util.spec_from_file_location('etm_toolbox_backend',source)\n    backend=importlib.util.module_from_spec(spec);sys.modules[spec.name]=backend;spec.loader.exec_module(backend)\n    backend.app.static_folder=str(etm_root/'web')\n    if not (etm_root/'web/app/embedding.js').is_file():\n        raise ValueError('ETM工程版本过旧，请同时更新两个仓库后再启动')\n    # A separate backend namespace preserves standalone ETM /api and records.\n    def embedded_index():\n        text=(etm_root/'web/index.html').read_text(encoding='utf8')\n        text=text.replace('href=\"/','href=\"/etm/').replace('src=\"/','src=\"/etm/')\n        if request.args.get('embedded')=='1':\n            buttons=[]\n            for identifier in ('toggle-settings','help'):\n                match=re.search(r'<button id=\"'+identifier+r'\"[^>]*>.*?</button>',text)\n                if match:buttons.append(match[0]);text=text.replace(match[0],'',1)\n            text=text.replace('<div class=\"record-toolbar\">','<div class=\"record-toolbar\"><div class=\"embedded-actions\">'+''.join(buttons)+'</div>',1)\n            text=text.replace('<body id=\"etm-app\">','<body id=\"etm-app\" data-embedded=\"1\" data-api-base=\"/etm/api/\">')\n            style='<style>body#etm-app[data-embedded]{min-height:0}body#etm-app[data-embedded]>header{display:none}body#etm-app[data-embedded]>.workspace{height:100vh}body#etm-app .embedded-actions{display:flex;gap:4px}</style>'\n            text=text.replace('</head>',style+'</head>')\n            diagnostics=\"\"\"<script>window.addEventListener('error',function(e){var el=document.getElementById('job-state');if(el){el.textContent='页面初始化失败：'+e.message;el.classList.add('bad');}});window.addEventListener('unhandledrejection',function(e){var el=document.getElementById('job-state');if(el){el.textContent='页面初始化失败：'+(e.reason&&e.reason.message||e.reason);el.classList.add('bad');}});</script>\"\"\"\n            text=text.replace('<script type=\"module\"',diagnostics+'<script type=\"module\"',1)\n        else:\n            text=text.replace('<body id=\"etm-app\">','<body id=\"etm-app\" data-api-base=\"/etm/api/\">')\n        return text\n    backend.app.view_functions['index']=embedded_index\n    backend.app.add_url_rule('/integration.json','toolbox_integration',lambda:jsonify(protocol=1,backend='kingst',embedded=True))\n    @backend.app.after_request\n    def fresh_backend(response):\n        response.headers['Cache-Control']='no-store';return response\n    app=Flask('serial_etm_workbench',static_folder=None)\n    @app.before_request\n    def local_only():\n        if request.remote_addr not in ('127.0.0.1','::1'):abort(403)\n    @app.route('/etm-launcher.json')\n    def launcher_info():\n        return jsonify(protocol=1,serialRoot=str(serial_root),etmRoot=str(etm_root))\n    @app.route('/',defaults={'path':'index.html'})\n    @app.route('/<path:path>')\n    def static_file(path):\n        # Only public files. Never expose Git metadata, backend records or temp files.\n        if any(part.startswith('.') for part in Path(path).parts) or Path(path).parts[0] in ('tmp','node_modules','captures','records'):\n            abort(404)\n        return send_from_directory(serial_root,path)\n    @app.after_request\n    def fresh_main(response):\n        response.headers['Cache-Control']='no-store';return response\n    return DispatcherMiddleware(app,{'/etm':backend.app})\n\n\nif __name__=='__main__':\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument('--port',type=int,default=8878)\n    parser.add_argument('--etm-root',type=Path,default=ROOT.parent/'web-etm-trace')\n    parser.add_argument('--serial-root',type=Path,default=ROOT)\n    args=parser.parse_args()\n    print(f'统一工作台：http://127.0.0.1:{args.port}/#etm',flush=True)\n    run_simple('127.0.0.1',args.port,create_application(args.etm_root,args.serial_root),threaded=True,use_reloader=False)\n","sha256":"adbbc44ae2af1b4d516c41076c49577e803c631d593c8275e514a1967abfdb89"}};
